import {videoLesson,observedBeats,labels,canRevealDiscussion} from './studio-model.js';
import {PRESENTER_PROFILES,PRESENTER_IDS} from './presenter-profiles.js';
import {PartyThread,partyKey,normalizeQuestion} from './party-state.js';
const $=id=>document.getElementById(id),set=(id,value)=>$(id).textContent=value,film=$('film');
const roles=PRESENTER_IDS,names=Object.fromEntries(PRESENTER_PROFILES.map(p=>[p.id,p.name])),classes=Object.fromEntries(PRESENTER_PROFILES.map(p=>[p.id,p.image]));
let roomView='room',selectedRole=null;
const threads=new Map(),spoken=new Set();let language='en',mode='fan',question='',unlocked=false,started=false,base='',queue=Promise.resolve(),voices=false,toastTimer;
const key=()=>partyKey(language,mode,question),clock=t=>`00:${Math.floor(t).toString().padStart(2,'0')}`;
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
film.muted=true;
const configReady=fetch('api-config.json').then(r=>r.json()).then(c=>{base=['localhost','127.0.0.1'].includes(location.hostname)?'':c.baseUrl||'';}).catch(()=>{});
function toast(message){set('toast',message);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function cancelSpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function speakPosts(s){if(!voices||!unlocked||$('watch').hidden||!s)return;for(const role of roles){const post=s.posts.get(role),id=key()+role;if(!post||spoken.has(id))continue;spoken.add(id);const utterance=new SpeechSynthesisUtterance(`${names[role]}. ${post.summary}`);utterance.lang={en:'en-US',es:'es-ES',pt:'pt-BR'}[language];const available=speechSynthesis.getVoices().filter(v=>v.lang.startsWith(language));if(available.length)utterance.voice=available[roles.indexOf(role)%available.length];utterance.rate=1;utterance.onerror=e=>{if(!['canceled','interrupted'].includes(e.error)){voices=false;set('voices','Voices off');$('voices').setAttribute('aria-pressed','false');toast('Browser speech is unavailable on this device. The conversation is still available as text.');}};speechSynthesis.speak(utterance);}}
async function seek(at){film.pause();cancelSpeech();if(film.readyState<1)await new Promise((resolve,reject)=>{const done=()=>{clearTimeout(timer);film.removeEventListener('loadedmetadata',done);resolve();},timer=setTimeout(()=>{film.removeEventListener('loadedmetadata',done);reject(Error('Video not ready'));},8000);film.addEventListener('loadedmetadata',done);film.load();});film.currentTime=Math.max(0,Math.min(8,at));started=true;$('opening').hidden=true;renderPlayback();}
function buildBeats(){$('beats').replaceChildren();for(const [i,b]of observedBeats(8,language).entries()){const button=el('button','beat');button.dataset.id=b.id;button.append(el('b','',`0${i+1}`),el('strong','',b.title),el('small','',`${b.at.toFixed(2)}s`));button.addEventListener('click',()=>seek(b.at).catch(mediaError));$('beats').append(button);}}
function renderLesson(){const t=Math.min(8,film.currentTime||0),story=videoLesson(t,mode,language);set('bug-clock',clock(t));set('current-time',clock(t));$('scrub').value=t;set('lesson-time',clock(t));set('lesson-mode',labels[language][mode]);set('lesson-title',story.title);set('lesson-body',story.body);$('math-card').hidden=!story.math;set('math-card',story.math||'');$('broadcast-caption').hidden=!started||!story.activeId;set('caption-kicker',labels[language][mode]);set('caption-title',story.title);if(started){set('now-label',film.ended?'YOUR TAKE':labels[language][mode]);set('now-copy',story.body);}for(const b of $('beats').children){b.classList.toggle('selected',b.dataset.id===story.activeId);b.setAttribute('aria-current',String(b.dataset.id===story.activeId));}$('evidence-list').replaceChildren();for(const b of story.evidence){const row=el('div','evidence-item'),button=el('button','',`${b.at.toFixed(2)}s · ${b.title} ↗`);button.addEventListener('click',()=>{$('learn-dialog').close();seek(b.at).catch(mediaError);});row.append(button,el('p','',b.observation));$('evidence-list').append(row);}if(!story.evidence.length)$('evidence-list').append(el('p','','Play to reveal the reviewed observations.'));}
function renderPlayback(){set('play',film.paused?'▶':'Ⅱ');$('play').setAttribute('aria-label',film.paused?'Play film':'Pause film');$('end-replay').hidden=!film.ended;renderLesson();if(canRevealDiscussion(film.currentTime,unlocked)&&!unlocked){unlocked=true;renderConversation();startDiscussion();}}
function renderConversation(){const s=threads.get(key());document.dispatchEvent(new CustomEvent('btr-contributions',{detail:{posts:unlocked?[...(s?.posts.values()||[])]:[],language,mode}}));renderAgentRoom(s);const container=$('conversation'),nearBottom=container.scrollHeight-container.scrollTop-container.clientHeight<100;const enabled=unlocked&&!s?.pending;$('question').disabled=!enabled;$('send-question').disabled=!enabled;for(const button of document.querySelectorAll('[data-question]'))button.disabled=!enabled;$('question').placeholder=unlocked?'Ask the crew about this play…':'Watch the play, then ask the crew…';$('opening-thread').hidden=!question;$('export').disabled=!unlocked||!s?.posts.size;
 if(!unlocked){set('party-status',started?'Discussion opens after the final frame.':'FULL-CLIP DISCUSSION · WAITING FOR PLAY');return;}
 container.replaceChildren();if(question)container.append(el('p','viewer-message',question));let count=0;
 for(const role of roles){if(roomView==='narrative'&&role!=='presenter'||roomView==='room'&&selectedRole&&role!==selectedRole)continue;const post=s?.posts.get(role),draft=$('stream-live').checked?s?.drafts.get(role):null;if(!post&&!draft)continue;count++;const root=el('article',`message ${classes[role]}${post?'':' draft'}`),meta=el('div','message-meta');meta.append(el('span',`crew-avatar ${classes[role]}`,names[role][0]),el('b','message-name',names[role]),el('span','message-badge',post?(post.engine==='azure_openai'?'AI':'REVIEWED NOTES'):'DRAFT · UNVALIDATED'));root.append(meta,el('p','',post?.summary||draft.summary));if(post){renderSpecialistTools(root,post.tools);const citations=el('div','citations');for(const id of post.evidence_ids||[]){const b=observedBeats(8,language).find(x=>x.id===id);if(!b)continue;const button=el('button','',`${b.at.toFixed(2)}s ↗`);button.title=b.title;button.setAttribute('aria-label',`Replay: ${b.title}`);button.addEventListener('click',()=>seek(b.at).catch(mediaError));citations.append(button);}root.append(citations);if(post.caution){const details=el('details');details.append(el('summary','','What remains uncertain'),el('p','',post.caution));root.append(details);}}container.append(root);}
 if(!count){const welcome=el('div','welcome');welcome.append(el('span','welcome-mark','“'),el('h3','',roomView==='narrative'?'The story is taking shape.':selectedRole?`${names[selectedRole]} is up next.`:'The conversation is starting.'),el('p','',roomView==='narrative'?'The Host’s final contribution will appear here after Scout, Guide, Vector and Check have weighed in.':'The panel uses the reviewed moments. Contributions appear as they arrive.'));container.append(welcome);}
 if(s?.error){const retry=el('button','retry','Retry this conversation ↗');retry.addEventListener('click',()=>startDiscussion());container.append(retry);}
 const fallback=[...(s?.posts.values()||[])].some(p=>p.engine!=='azure_openai');set('party-status',s?.error||(!s?'Ready for your perspective.':s.complete?(fallback?'Reviewed notes · AI temporarily unavailable':'Full-clip conversation · tap a timestamp to replay'):`${names[s.speaker]||'The crew'} is thinking…`));if(nearBottom)container.scrollTop=container.scrollHeight;speakPosts(s);
}
function renderSpecialistTools(root,tools){
 if(!tools?.items?.length)return;
 const panel=el('details','specialist-tools');panel.open=tools.kind==='calculations';panel.append(el('summary','',tools.kind==='calculations'?({en:'Show the working · calculated by code',es:'Ver el cálculo · calculado por código',pt:'Ver o cálculo · calculado por código'}[language]):({en:'Football glossary · curated definitions',es:'Glosario de fútbol · definiciones revisadas',pt:'Glossário de futebol · definições revisadas'}[language])));
 for(const item of tools.items){const row=el('div','specialist-tool');row.append(el('strong','',item.label));if(item.expression)row.append(el('code','',item.expression));if(item.text)row.append(el('p','',item.text));if(item.note)row.append(el('p','tool-note',item.note));const links=el('div','citations');for(const id of item.evidence_ids||[]){const beat=observedBeats(8,language).find(b=>b.id===id);if(beat){const link=el('button','',beat.at.toFixed(2)+'s ↗');link.setAttribute('aria-label','Replay: '+beat.title);link.addEventListener('click',()=>seek(beat.at).catch(mediaError));links.append(link);}}row.append(links);panel.append(row);}root.append(panel);
}
function startDiscussion(){const k=key();if(threads.get(k)?.pending||threads.get(k)?.complete)return;const s=new PartyThread(language,mode,question);threads.set(k,s);renderConversation();queue=queue.then(async()=>{if(k!==key()){threads.delete(k);return;}try{await configReady;const response=await fetch(base+'/api/desk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({language:s.language,mode:s.mode,question:s.question})});if(!response.ok){const error=await response.json().catch(()=>({}));throw Error(error.error||'The crew is unavailable. Please retry.');}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});if(buffer.length>256000)throw Error('Conversation frame too large');let split;while((split=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,split);buffer=buffer.slice(split+2);let type='',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))type=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim();}if(!data)continue;const item=JSON.parse(data);if(type==='error')throw Error(item.message);s.accept(type,item);if(k===key())renderConversation();}}if(!s.complete)throw Error('The conversation disconnected. Retry to finish it.');}catch(error){s.fail(error.message);}finally{if(k===key())renderConversation();}});}
function changeThread(){cancelSpeech();renderConversation();if(unlocked||started)startDiscussion();}
function ask(value){try{const normalized=normalizeQuestion(value);if(!normalized)return;question=normalized;$('question').value='';changeThread();}catch(e){toast(e.message);}}
function mediaError(){toast('The film could not play. Check your connection and try again.');}
async function playFilm(){try{if(film.ended)film.currentTime=0;await film.play();started=true;$('opening').hidden=true;renderPlayback();startDiscussion();}catch{mediaError();}}
async function restart(){try{await seek(0);await playFilm();}catch{mediaError();}}
$('hero-play').addEventListener('click',playFilm);$('play').addEventListener('click',()=>film.paused?playFilm():film.pause());$('restart').addEventListener('click',restart);$('end-replay').addEventListener('click',restart);$('scrub').addEventListener('input',()=>seek(Number($('scrub').value)).catch(mediaError));for(const event of ['timeupdate','play','pause','ended','seeked'])film.addEventListener(event,renderPlayback);film.addEventListener('error',mediaError);film.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();film.paused?playFilm():film.pause();}});
$('slow').addEventListener('click',()=>{film.playbackRate=film.playbackRate===1?.5:1;set('slow',film.playbackRate===1?'1×':'½×');$('slow').setAttribute('aria-pressed',String(film.playbackRate===.5));});$('sound').addEventListener('click',()=>{film.muted=!film.muted;set('sound',film.muted?'Sound off':'Sound on');$('sound').setAttribute('aria-pressed',String(!film.muted));});$('fullscreen').addEventListener('click',()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else if($('player').requestFullscreen)$('player').requestFullscreen().catch(()=>toast('Fullscreen is unavailable.'));else if(film.webkitEnterFullscreen)film.webkitEnterFullscreen();});
$('perspective').addEventListener('change',()=>{mode=$('perspective').value;question='';renderLesson();changeThread();});$('story-language').addEventListener('change',()=>{language=$('story-language').value;question='';for(const option of $('perspective').options)option.textContent=labels[language][option.value];buildBeats();renderLesson();changeThread();});$('stream-live').addEventListener('change',renderConversation);
$('question-form').addEventListener('submit',e=>{e.preventDefault();ask($('question').value);});for(const b of document.querySelectorAll('[data-question]'))b.addEventListener('click',()=>ask(b.dataset.question));$('opening-thread').addEventListener('click',()=>{question='';changeThread();});
$('voices').addEventListener('click',()=>{if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){toast('This browser does not support spoken contributions.');return;}voices=!voices;set('voices',voices?'Voices on':'Voices off');$('voices').setAttribute('aria-pressed',String(voices));cancelSpeech();if(voices){for(const role of roles)spoken.delete(key()+role);speakPosts(threads.get(key()));}});
$('party-toggle').addEventListener('click',()=>{const hidden=document.body.classList.toggle('party-closed');$('party-toggle').setAttribute('aria-pressed',String(!hidden));});$('replays').addEventListener('click',()=>{$('beats').hidden=!$('beats').hidden;$('replays').setAttribute('aria-expanded',String(!$('beats').hidden));});
for(const name of ['learn','settings','about']){$(name).addEventListener('click',()=>{if(name==='learn')film.pause();$(name+'-dialog').showModal();});$('close-'+name).addEventListener('click',()=>$(name+'-dialog').close());}$('learn-inline').addEventListener('click',()=>{film.pause();$('learn-dialog').showModal();});
function showLab(value){document.querySelectorAll('.extension-view').forEach(n=>n.hidden=true);document.querySelectorAll('.extension-nav').forEach(n=>{n.classList.remove('selected');n.setAttribute('aria-pressed','false');});document.dispatchEvent(new CustomEvent('btr-section',{detail:value?'lab':'watch'}));film.pause();cancelSpeech();$('watch').hidden=value;$('lab').hidden=!value;for(const [id,selected]of [['watch-nav',!value],['lab-nav',value]]){$(id).classList.toggle('selected',selected);$(id).setAttribute('aria-pressed',String(selected));}if(value&&!$('simulation').getAttribute('src'))$('simulation').src='simulation.html?embedded=1';if(!value)$('simulation').contentWindow?.postMessage({type:'btr-pause-lab'},location.origin);}
$('watch-nav').addEventListener('click',()=>showLab(false));$('lab-nav').addEventListener('click',()=>showLab(true));$('back-watch').addEventListener('click',()=>showLab(false));
$('export').addEventListener('click',()=>{const s=threads.get(key());if(!unlocked||!s?.posts.size)return;const data={schema:'btr.watch-party.v1',clip_id:'featured',synthetic:true,evidence_source:'manual-review',language,audience:mode,question,discussion_scope:'full-clip',evidence:observedBeats(8,language),contributions:[...s.posts.values()],complete:s.complete,limits:['No automatic video analysis.','Unknown shot result, score, speed and verified player identity.']},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download=`btr-watch-party-${language}-${mode}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
function renderAgentRoom(s){
 for(const node of document.querySelectorAll('[data-agent]')){const role=node.dataset.agent,active=!!s?.pending&&s.speaker===role;node.classList.toggle('active',active);node.setAttribute('aria-pressed',String(selectedRole===role&&roomView==='room'));node.querySelector('.agent-state').textContent=active?'COMPOSING':s?.posts.has(role)?'READY':'WAITING';}
 $('all-agents').hidden=!selectedRole;
}
function setRoomView(view){roomView=view;for(const name of ['room','narrative']){$(name+'-tab').setAttribute('aria-selected',String(name===view));$(name+'-panel').hidden=name!==view;}renderConversation();}
for(const view of ['room','narrative'])$(view+'-tab').addEventListener('click',()=>setRoomView(view));
for(const node of document.querySelectorAll('[data-agent]'))node.addEventListener('click',()=>{selectedRole=selectedRole===node.dataset.agent?null:node.dataset.agent;renderConversation();});
$('all-agents').addEventListener('click',()=>{selectedRole=null;renderConversation();});
$('clean-feed').addEventListener('click',()=>{const clean=$('player').classList.toggle('clean-feed');$('clean-feed').setAttribute('aria-pressed',String(clean));});
$('replays').addEventListener('click',()=>document.querySelector('.timeline-heading').hidden=$('beats').hidden);
for(const tab of [$('room-tab'),$('narrative-tab')])tab.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?'room':event.key==='End'?'narrative':roomView==='room'?'narrative':'room';setRoomView(next);$(next+'-tab').focus();}});
configReady.then(()=>fetch(base+'/api/health')).then(r=>{if(!r.ok)throw Error('Offline');return r.json();}).then(h=>{$('connection-status').replaceChildren(el('i'),document.createTextNode(h.ai_configured?'AZURE AI READY':'REVIEWED NOTES'));$('connection-status').classList.toggle('ready',!!h.ai_configured);}).catch(()=>{$('connection-status').replaceChildren(el('i'),document.createTextNode('CONNECT ON PLAY'));});
buildBeats();renderLesson();$('hero-play').disabled=false;$('play').disabled=false;set('loading-note','8-second original · AI conversation follows');

document.addEventListener('btr-request-contributions',()=>renderConversation());
document.addEventListener('btr-profile-role',event=>{showLab(false);setRoomView('room');selectedRole=roles.includes(event.detail)?event.detail:null;renderConversation();document.body.classList.remove('party-closed');$('party-toggle').setAttribute('aria-pressed','true');$('party').scrollIntoView({block:'start',behavior:'smooth'});});
document.addEventListener('btr-section',event=>{if(!['watch','lab'].includes(event.detail)){film.pause();cancelSpeech();$('watch').hidden=true;$('lab').hidden=true;$('simulation').contentWindow?.postMessage({type:'btr-pause-lab'},location.origin);}});

document.addEventListener('btr-agent-question',event=>{document.dispatchEvent(new CustomEvent('btr-profile-role',{detail:event.detail.role}));$('question').value=event.detail.question;toast(unlocked?'Your question is ready. Send it to the room.':'Watch the film, then send your question to the room.');if(!$('question').disabled)$('question').focus({preventScroll:true});});
